// SQL of the portfolio of the member's own creator account (docs/mvp/07 RG77 to RG84; 0242, 0243;
// jalons/l2g/modele.md §3, points 3, 4, 10; commit 07). Every statement runs in the member's
// transaction, as influx_creator: the account is the one of the transaction context, never a
// parameter. The writes go through the doors of 0242 and 0243 only (owned by
// influx_creator_profile_definer); the reads are bound to the account by the policy of 0242. The key
// of an object is generated by the base and read here only to reach Storage: it never leaves
// apps/api (T9.2, T9.9). The checksum, the lock, the agent and the internal comment are not read
// (the creator holds no right on them, modele §2).
import { sql } from "drizzle-orm";
import type { Transaction } from "../../../../db/index.ts";

const ISO_UTC = 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"';

/** The answer the creator reads lists 64 visuals at most (portfolioResponseSchema). */
export const PORTFOLIO_LIST_LIMIT = 64;

/** A visual being deposited: its row and the key of its object, both the base's (T9.9). */
export type PortfolioUploadRef = { itemId: string; objectKey: string };

/** A visual of the creator as he reads it (modele point 10: neither uploading nor purged). */
export type StoredPortfolioItem = {
  id: string;
  state: "pending" | "approved" | "rejected" | "withdrawn" | "purging";
  displayOrder: number | null;
  caption: string | null;
  brandDeclared: boolean;
  width: number;
  height: number;
  byteSize: number;
  replacesItemId: string | null;
  replacementPending: boolean;
  captionPending: boolean;
  rejectionReasonCode: string | null;
  retentionDueAt: string | null;
  createdAt: string;
  decidedAt: string | null;
};

/** A Postgres uuid-array literal (the identifiers are checked by the schema of the route). */
function uuidArray(values: readonly string[]): string {
  return `{${values.join(",")}}`;
}

/** (b) quotas, place and row, before any byte is decoded (0242 begin_portfolio_upload). */
export async function beginPortfolioUpload(
  tx: Transaction,
  receivedBytes: number,
  replacesItemId: string | null,
): Promise<PortfolioUploadRef> {
  const rows = await tx.execute<{ item_id: string; object_key: string }>(
    sql`select item_id::text as item_id, object_key
          from profiles.begin_portfolio_upload(${receivedBytes}::integer, ${replacesItemId}::uuid)`,
  );
  const row = rows[0];
  if (row === undefined) {
    throw new Error("begin_portfolio_upload returned no row");
  }
  return { itemId: row.item_id, objectKey: row.object_key };
}

/** (c) the bytes refused: the uploading row forgotten (0242). */
export async function discardPortfolioUpload(
  tx: Transaction,
  itemId: string,
): Promise<void> {
  await tx.execute(
    sql`select profiles.discard_portfolio_upload(${itemId}::uuid)`,
  );
}

/** (d) the write failed, or the storage refused: the uploading row to purging (0242). */
export async function failPortfolioUpload(
  tx: Transaction,
  itemId: string,
): Promise<void> {
  await tx.execute(sql`select profiles.fail_portfolio_upload(${itemId}::uuid)`);
}

/** (e) the object stored: the visual pending, in queue 3 (0242 store_portfolio_item). */
export async function storePortfolioItem(
  tx: Transaction,
  itemId: string,
  output: {
    byteSize: number;
    width: number;
    height: number;
    checksumHex: string;
  },
): Promise<void> {
  await tx.execute(
    sql`select * from profiles.store_portfolio_item(
          ${itemId}::uuid, ${output.byteSize}::integer, ${output.width}::integer,
          ${output.height}::integer, ${output.checksumHex}::text)`,
  );
}

/** RG84: the order of the placed visuals, each once (0242 reorder_own_portfolio). */
export async function reorderOwnPortfolio(
  tx: Transaction,
  itemIds: readonly string[],
): Promise<void> {
  await tx.execute(
    sql`select profiles.reorder_own_portfolio(${uuidArray(itemIds)}::uuid[])`,
  );
}

/** A visual withdrawn by its creator, kept 30 days (0242); false when neither pending nor approved. */
export async function removeOwnPortfolioItem(
  tx: Transaction,
  itemId: string,
): Promise<boolean> {
  const rows = await tx.execute<{ removed: boolean }>(
    sql`select profiles.remove_own_portfolio_item(${itemId}::uuid) as removed`,
  );
  return rows[0]?.removed === true;
}

/** RG82, RG83, RG9: the caption and the box (0243); the status of the revision, null when direct. */
export async function setOwnPortfolioCaption(
  tx: Transaction,
  itemId: string,
  caption: string | null,
  brandDeclared: boolean,
): Promise<string | null> {
  const rows = await tx.execute<{ revision_status: string | null }>(
    sql`select revision_status::text as revision_status
          from profiles.set_own_portfolio_caption(
                 ${itemId}::uuid, ${caption}::text, ${brandDeclared}::boolean)`,
  );
  return rows[0]?.revision_status ?? null;
}

type ItemRow = {
  id: string;
  state: StoredPortfolioItem["state"];
  display_order: number | null;
  caption: string | null;
  brand_declared: boolean;
  width: number;
  height: number;
  byte_size: number;
  replaces_item_id: string | null;
  replacement_pending: boolean;
  caption_pending: boolean;
  rejection_reason_code: string | null;
  retention_due_at: string | null;
  created_at: string;
  decided_at: string | null;
};

/**
 * His visuals as he reads them (modele point 10): every state but `uploading` and `purged`, a
 * deposit that failed before its storage apart (no visual to show); the
 * pending and approved ones first, in his order (a pending replacement after the placed ones), then
 * the others from the latest; 64 at most (eight placed and a replacement each at most, are never cut).
 */
export async function readOwnPortfolioItems(
  tx: Transaction,
  only: string | null = null,
): Promise<StoredPortfolioItem[]> {
  const rows = await tx.execute<ItemRow>(sql`
    select v.id::text as id, v.state::text as state, v.display_order, v.caption,
           v.brand_declaration_id is not null as brand_declared,
           v.width, v.height, v.byte_size, v.replaces_item_id::text as replaces_item_id,
           exists (select 1 from profiles.portfolio_items r
                    where r.replaces_item_id = v.id and r.account_id = v.account_id
                      and r.state = 'pending') as replacement_pending,
           exists (select 1 from profiles.creator_field_revisions f
                    where f.account_id = v.account_id
                      and f.field_code = 'creator.portfolio_caption'
                      and f.row_key = v.id::text and f.status = 'pending_review') as caption_pending,
           v.rejection_reason_code::text as rejection_reason_code,
           to_char(v.retention_due_at at time zone 'UTC', ${ISO_UTC}) as retention_due_at,
           to_char(v.created_at at time zone 'UTC', ${ISO_UTC}) as created_at,
           to_char(v.decided_at at time zone 'UTC', ${ISO_UTC}) as decided_at
      from profiles.portfolio_items v
     where v.account_id = (select influx.current_account_id())
       and v.state not in ('uploading', 'purged')
       -- a failed deposit (purging, never stored) has no visual to show
       and v.stored_at is not null
       and (${only}::uuid is null or v.id = ${only}::uuid)
     order by (v.state not in ('pending', 'approved')), v.display_order nulls last,
              v.created_at desc, v.id
     limit ${PORTFOLIO_LIST_LIMIT}`);
  return rows.map((row): StoredPortfolioItem => ({
    id: row.id,
    state: row.state,
    displayOrder: row.display_order,
    caption: row.caption,
    brandDeclared: row.brand_declared,
    width: row.width,
    height: row.height,
    byteSize: row.byte_size,
    replacesItemId: row.replaces_item_id,
    replacementPending: row.replacement_pending,
    captionPending: row.caption_pending,
    rejectionReasonCode: row.rejection_reason_code,
    retentionDueAt: row.retention_due_at,
    createdAt: row.created_at,
    decidedAt: row.decided_at,
  }));
}

/** What the read of one of his visuals needs (modele point 10); null when unknown or another's. */
export async function readOwnPortfolioObject(
  tx: Transaction,
  itemId: string,
): Promise<{
  objectKey: string;
  width: number;
  height: number;
  byteSize: number;
} | null> {
  const rows = await tx.execute<{
    object_key: string;
    width: number;
    height: number;
    byte_size: number;
  }>(sql`
    select v.object_key, v.width, v.height, v.byte_size
      from profiles.portfolio_items v
     where v.id = ${itemId}::uuid
       and v.account_id = (select influx.current_account_id())
       and v.state not in ('uploading', 'purged')
       and v.stored_at is not null`);
  const row = rows[0];
  return row === undefined
    ? null
    : {
        objectKey: row.object_key,
        width: row.width,
        height: row.height,
        byteSize: row.byte_size,
      };
}
